function apexRaceMaterial(key, width, height, draw, properties = {}) {
  if (bo.has(key)) return bo.get(key);
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  draw(canvas.getContext('2d'), width, height);
  const map = new $i(canvas);
  map.name = key;
  map.colorSpace = wt;
  map.anisotropy = 8;
  map.userData.mimeType = 'image/jpeg';
  const material = new $r({
    map, color: 0xffffff, roughness: .47, metalness: .24,
    clearcoat: .72, clearcoatRoughness: .31,
    normalMap: cn['metal-nor_gl'], normalScale: new re(.055, .055),
    roughnessMap: cn['metal-arm'], ...properties,
  });
  material.name = key;
  material.userData.sign = true;
  bo.set(key, material);
  return material;
}
function apexDecal(ctx, text, x, y, size, color, align = 'left') {
  ctx.fillStyle = color;
  ctx.font = 'italic 900 ' + size + 'px sans-serif';
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';
  ctx.fillText(text, x, y);
}
function apexCarbon() {
  return apexRaceMaterial('Carbon weave', 256, 256, (ctx, w, h) => {
    ctx.fillStyle = '#1c2020'; ctx.fillRect(0, 0, w, h);
    for (let x = 0; x < w; x += 4) for (let y = 0; y < h; y += 4) {
      ctx.fillStyle = ((x + y) % 8) ? '#252929' : '#171a1b';
      ctx.fillRect(x, y, 3, 3);
    }
  }, {metalness: .12, roughness: .79, clearcoat: .13});
}
function apexBox(builder, material, x,y,z,w,h,d, radius=.022, pitch=0,yaw=0,roll=0) {
  builder.add(new bn(w,h,d,2,radius),material,x,y,z,pitch,yaw,roll);
}
function apexLever(builder, material, from, to, radius) {
  builder.beam(it(...from),it(...to),radius,material);
}
