function apexPrintGrain(ctx,w,h,seed,coverage=.095) {
  for(let i=0;i<Math.round(w*h/92);i++){
    const x=(i*173+Math.floor(i/113)*73+seed*11)%w,y=(i*317+Math.floor(i/67)*13+seed*7)%h;
    ctx.fillStyle=(i%4?'rgba(18,23,19,':'rgba(247,239,207,')+(coverage*(1+i%7)/7)+')';
    ctx.fillRect(x,y,1+i%3,1+(i%11===0?1:0));
  }
}
